   and e.title = 'Comparing relative position in normal distributions' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;

-- 4. Guards: no dead figure, and every entry this batch covers got its figures.
do $$
declare v_dead text; v_n int;
begin
  select string_agg(f.figure_id, ', ') into v_dead
    from app.figures f left join app.figure_uses u on u.figure_id = f.figure_id
   where f.figure_id in ('stats-normal-curve', 'stats-standard-normal', 'stats-empirical-rule', 'stats-normal-area', 'stats-chi-square-shapes', 'stats-critical-value-z', 'stats-pvalue-right-tail', 'stats-pvalue-left-tail', 'stats-pvalue-two-tailed', 'stats-normal-relative-position') and u.figure_id is null;
  if v_dead is not null then
    raise exception 'figures with no use, refusing to ship dead rows: %', v_dead;
  end if;
  select count(*) into v_n from app.figures where figure_id in ('stats-normal-curve', 'stats-standard-normal', 'stats-empirical-rule', 'stats-normal-area', 'stats-chi-square-shapes', 'stats-critical-value-z', 'stats-pvalue-right-tail', 'stats-pvalue-left-tail', 'stats-pvalue-two-tailed', 'stats-normal-relative-position');
  if v_n <> 10 then
    raise exception 'expected 10 figures, found %', v_n;
  end if;
end $$;

commit;
